?><!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ニュース管理</title><style>body{font-family:system-ui;margin:0;background:#f5fbf9;color:#174c47}.top{background:#fff;padding:16px 5%;display:flex;justify-content:space-between;position:sticky;top:0}.wrap{width:min(1100px,92%);margin:28px auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.box{background:#fff;border:1px solid #dcece7;border-radius:16px;padding:20px}input,textarea,select{width:100%;padding:10px;margin:6px 0 14px;border:1px solid #cfe4de;border-radius:9px;box-sizing:border-box}textarea{min-height:220px}button,.btn{background:#1d8f7a;color:#fff;border:0;padding:10px 16px;border-radius:9px;text-decoration:none;cursor:pointer}.danger{background:#b44747}.item{border:1px solid #e1eee9;padding:14px;border-radius:10px;margin:8px 0;background:#fff}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><strong>🍃 KGP 管理画面</strong><a href="/logout.php">ログアウト</a></header><main class="wrap"><div class="grid"><section class="box"><h2>ニュースを追加</h2><form method="post" action="/save-news.php"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf())?>"><input name="title" placeholder="タイトル" required><input name="slug" placeholder="URLスラッグ（空欄なら自動生成）"><input name="category" value="お知らせ"><input name="excerpt" placeholder="概要"><input name="cover_image_url" placeholder="カバー画像URL"><label><input type="checkbox" name="published" value="1"> 公開する</label><label>公開日時<input type="datetime-local" name="published_at"></label><label>本文<div id="editor" contenteditable="true" style="min-height:220px;border:1px solid #cfe4de;border-radius:9px;padding:12px;background:#fff"></div></label><input type="hidden" name="content_html" id="content_html"><div style="display:flex;gap:6px;flex-wrap:wrap"><button type="button" onclick="cmd('bold')">太字</button><button type="button" onclick="cmd('insertUnorderedList')">箇条書き</button><button type="button" onclick="cmd('formatBlock','<h2>')">見出し</button><button type="button" onclick="cmd('formatBlock','<p>')">段落</button></div><button style="margin-top:10px">保存</button></form><script>function cmd(a,b=null){document.execCommand(a,false,b);document.getElementById('editor').focus()}document.querySelector('form[action="/save-news.php"]').addEventListener('submit',()=>document.getElementById('content_html').value=document.getElementById('editor').innerHTML)</script></form></section><section class="box"><h2>ニュース一覧</h2><?php foreach($items as $n):?><article class="item"><strong><?=htmlspecialchars($n['title'])?></strong><br><small><?=htmlspecialchars($n['category'])?> / <?=($n['published']?'公開':'下書き')?></small><p><?=htmlspecialchars($n['excerpt'])?></p><a class="btn" href="/edit-news.php?id=<?=(int)$n['id']?>">編集</a></article><?php endforeach;?></section></div></main></body></html>
